/**
 * Pocket KO→EN reader dictionary.
 *
 * The companion to `en-ko.ts`, for when the story body is shown in Korean and
 * a learner taps a word. Same rules: in-house, offline, short glosses picked
 * for the sense our graded readers use.
 *
 * Korean is agglutinative, so this table mixes two kinds of key:
 *   1. dictionary head-words — nouns (`사람`), verb/adjective `-다` forms
 *      (`말하다`, `작다`), adverbs, particles; `ko-stem.ts` folds inflected
 *      surface forms back to these.
 *   2. a set of very common inflected forms verbatim (`있었어요`, `그녀는`,
 *      `작은`) so the frequent taps resolve instantly even when the stemmer
 *      would miss.
 *
 * When a lesson adds Korean the reader can't gloss, add it here one line each —
 * keep keys grouped by part of speech and roughly frequency-ordered. Proper
 * names are tagged "(name)" / "(place)" so a learner sees it isn't a word.
 */
